<?php
namespace App\Services;
use App\Jobs\SendCommunicationDelivery;use App\Models\{CommunicationCampaign,CommunicationDelivery};use Illuminate\Support\Facades\DB;
class CommunicationCampaignService{public function queue(CommunicationCampaign $c):array{abort_unless(in_array($c->status,['approved','scheduled']),422,'Campaign must be approved.');$rules=$c->audience_rules??$c->segment?->rules??[];$type=$c->segment?->audience_type??($rules['audience_type']??'guardians');$people=app(AudienceResolver::class)->resolve($type,$rules);$rate=(float)config('services.sms.cost_per_segment',0);$queued=$skipped=$segments=0;DB::transaction(function()use($c,$people,$rate,&$queued,&$skipped,&$segments){foreach($people as $p){if(!$this->allowed($p['type'],$p['id'],$c->channel,$c->category)){$skipped++;continue;}$destination=$this->destination($p,$c->channel);if(!$destination){$skipped++;continue;}$metric=MessageMetrics::calculate($c->body,$c->channel==='sms'?$rate:0);$d=CommunicationDelivery::firstOrCreate(['communication_campaign_id'=>$c->id,'channel'=>$c->channel,'destination'=>$destination],['recipient_type'=>$p['type'],'recipient_id'=>$p['id'],'recipient_name'=>$p['name'],'segments'=>$metric['segments'],'estimated_cost'=>$metric['estimated_cost'],'status'=>'queued']);if($d->wasRecentlyCreated){SendCommunicationDelivery::dispatch($d->id)->afterCommit();$queued++;$segments+=$metric['segments'];}}$c->update(['status'=>'processing','recipient_count'=>count($people),'skipped_count'=>$skipped,'total_segments'=>$segments,'estimated_cost'=>round($segments*$rate,4)]);});return compact('queued','skipped');}
 private function allowed($type,$id,$channel,$category):bool{$pref=DB::table('communication_preferences')->where(['recipient_type'=>$type,'recipient_id'=>$id,'channel'=>$channel])->whereIn('category',['*',$category])->orderByRaw("category='*' asc")->first();if($pref)return(bool)$pref->is_opted_in;if($type==='guardian'){$g=DB::table('guardians')->find($id);$prefs=json_decode($g?->notification_preferences??'{}',true);if(array_key_exists($channel,$prefs)&&!(bool)$prefs[$channel])return false;if(array_key_exists($category,$prefs)&&!(bool)$prefs[$category])return false;}return true;}
 private function destination(array $p,string $channel):?string{return match($channel){'sms','whatsapp'=>$p['phone'],'email'=>$p['email'],'push'=>DB::table('push_subscriptions')->where('user_id',$p['user_id'])->latest('last_used_at')->value('endpoint'),default=>null};}}
